<script setup>
import {computed,ref,watch} from 'vue';
import TeamMembers from './TeamMembers.vue';
import {savedTeam,savedTeamMe} from './team-settings-store.mjs';
import {issueOwnership} from './team-members.mjs';
import Icon from './HelmLabIcon.vue';
import IssueReadiness from './IssueReadiness.vue';
import DailyReadinessPanel from './DailyReadinessPanel.vue';
import {changeTracker,trackerBusy,trackerError,selectedTracker} from './release-trackers-store.mjs';
import {pullMyWork} from './my-work-store.mjs';
import {dailyReadiness,changeDailyReadiness,dailyReadinessBusy} from './daily-readiness-store.mjs';
import {trackerIssues,sameWorkScope,milestoneKey} from './release-trackers.mjs';
import {myWorkRows,myWorkMetrics,filterMyWork} from './my-work.mjs';
import {issuePackageSummaries,openIssuePackage,createIssuePackageFromIssue} from './issue-packages-store.mjs';
const props=defineProps({tracker:Object,snapshot:Object});
const scanning=ref(false),scanError=ref(''),releaseLabel=ref(''),releaseNotice=ref(''),team=ref([]),me=ref(''),ownerFilter=ref('all');
watch(()=>props.tracker,t=>{team.value=[...(t?.teamMembers||savedTeam.value)];me.value=t?.teamMe||savedTeamMe.value;},{immediate:true});
watch(()=>props.tracker?.issueLabel,label=>{releaseLabel.value=label||'';},{immediate:true});
async function scanRelease(){releaseNotice.value='';scanError.value='';const ok=await changeTracker('scan',{...props.tracker,issueLabel:releaseLabel.value,teamMembers:team.value,teamMe:me.value});if(ok){milestone.value='';filter.value='';query.value='';releaseNotice.value='Release issues updated. Select an issue below to inspect it and create a issue package.';}else scanError.value=trackerError.value;}
const milestoneCounts=computed(()=>props.tracker?.milestones.map(m=>({...m,count:m.snapshot?.issues?.length||0}))||[]);

const scanConfig=computed(()=>props.tracker?(props.tracker.milestones.find(m=>milestoneKey(m.config)===milestone.value)|| (props.tracker.milestones.length===1?props.tracker.milestones[0]:null))?.config:props.snapshot?.config);
async function scan(){if(!scanConfig.value)return;scanning.value=true;scanError.value='';try{await pullMyWork(scanConfig.value);await changeDailyReadiness('scan');}catch(e){scanError.value=e.message;}finally{scanning.value=false;}}
const filter=ref('open'),query=ref(''),inspected=ref(''),milestone=ref('');
const rows=computed(()=>myWorkRows(props.tracker?{issues:trackerIssues([props.tracker],props.tracker.id,milestone.value)}:props.snapshot,issuePackageSummaries.value));
const metrics=computed(()=>myWorkMetrics(rows.value)),visible=computed(()=>filterMyWork(rows.value,filter.value,query.value).filter(row=>{const ownership=issueOwnership(row.issue,team.value,me.value);return ownerFilter.value==='all'||(ownerFilter.value==='mine'?ownership.mine:ownership.group===ownerFilter.value);}));
const ownershipCards=computed(()=>[{id:'all',label:'All issues'},{id:'mine',label:'Assigned to you'},{id:'team',label:'Assigned to your team'},{id:'unassigned',label:'Unassigned'},{id:'outside',label:'Outside your team'}].map(card=>({...card,count:rows.value.filter(row=>{const owner=issueOwnership(row.issue,team.value,me.value);return card.id==='all'||(card.id==='mine'?owner.mine:owner.group===card.id);}).length})));
const detail=computed(()=>rows.value.find(r=>r.issue.html_url===inspected.value));
const reportMatches=computed(()=>{const config=dailyReadiness.value.report?.config;return props.tracker?props.tracker.milestones.some(m=>sameWorkScope(m.config,config)&&(!milestone.value||milestoneKey(m.config)===milestone.value)):sameWorkScope(props.snapshot?.config,config);});
const cards=[{id:'open',label:'Remaining issues'},{id:'needsPlan',label:'Need a test plan'},{id:'needsReproduction',label:'Need reproduction'},{id:'needsValidation',label:'Ready for validation'},{id:'validated',label:'Validated · still open'},{id:'closed',label:'Closed on GitHub'}];
function open(row){const release=props.tracker?{id:props.tracker.id,name:props.tracker.name}:null;if(release)selectedTracker.value=release.id;if(row.pkg)openIssuePackage(row.pkg.id,'',release);else createIssuePackageFromIssue(row.issue,release);}
</script>
<template><div class="my-work">
<section v-if="tracker" class="mw-release-radar" aria-label="Release issue radar"><div class="mw-section-heading"><div><span class="mw-eyebrow">Issue Radar · {{tracker.name}}</span><h2>Find issues. Build your issue packages.</h2></div></div><form class="mw-queue-tools" @submit.prevent="scanRelease"><label>Team or custom labels<input v-model="releaseLabel" placeholder="team/frameworks" :disabled="trackerBusy"/></label><button class="mw-primary" :disabled="trackerBusy||(!tracker.milestones.length&&!tracker.planVersions?.length)">{{trackerBusy?'Loading release issues…':'Scan release issues'}}</button></form><p v-if="releaseLabel!==(tracker.issueLabel||'')" class="mw-caption">Label changed · Scan release issues to update the results below.</p><p class="mw-caption">Searches every release milestone and all owners. Enter any GitHub label; comma-separated labels must all match. Leave blank for all issues. Individually added issues stay in your queue.</p><details><summary>Team settings · {{team.length}} people</summary><TeamMembers v-model="team" v-model:me="me" :disabled="trackerBusy"/><p class="mw-caption">Choose Scan release issues to save these people with this tracker.</p></details><div class="mw-release-lines"><button class="mw-secondary" :aria-pressed="!milestone" @click="milestone=''">All release lines</button><button v-for="m in milestoneCounts" :key="milestoneKey(m.config)" class="mw-secondary" :aria-pressed="milestone===milestoneKey(m.config)" @click="milestone=milestoneKey(m.config)">{{m.snapshot?.milestone.title||'#'+m.config.milestone}} <strong>{{m.count}}</strong></button></div><div class="mw-release-lines"><button v-for="card in ownershipCards" :key="card.id" class="mw-secondary" :aria-pressed="ownerFilter===card.id" @click="ownerFilter=card.id">{{card.label}} <strong>{{card.count}}</strong></button></div><p v-if="!team.length" class="mw-caption">Add your team above to distinguish your team from other assignees.</p><p v-if="releaseNotice" role="status" class="mw-caption">{{releaseNotice}}</p></section>

<details v-if="tracker?.refreshedAt" class="mw-support" open><summary>Changes from refresh · {{new Date(tracker.refreshedAt).toLocaleString()}} · {{tracker.changes?.length||0}}</summary><p v-if="!tracker.changes?.length" class="mw-caption">No issue membership, milestone, owner, or status changes.</p><div v-for="change in tracker.changes||[]" :key="change.url" class="mw-change"><a :href="change.url" target="_blank" rel="noopener noreferrer">#{{change.number}} · {{change.title}}</a><p>{{change.reason}}</p></div></details>
<div class="mw-work-toolbar"><select v-if="tracker?.milestones.length" v-model="milestone" aria-label="Filter tracker milestone"><option value="">All linked milestones</option><option v-for="m in tracker.milestones" :key="milestoneKey(m.config)" :value="milestoneKey(m.config)">{{m.snapshot?.milestone.title}} · {{m.config.scope==='mine'?'Assigned to @'+m.config.user:m.config.scope==='unassigned'?'Unassigned':'All owners'}} · {{m.config.repo}}</option></select><button v-if="scanConfig" class="mw-secondary" :disabled="scanning||dailyReadinessBusy||dailyReadiness.report?.status==='running'" @click="scan">{{scanning?'Preparing scan…':'Scan milestone readiness'}}</button><span class="mw-caption">{{rows.length}} issues · {{tracker?.name||snapshot?.milestone.title}} · saved GitHub observations</span></div>
<p v-if="scanError" role="alert" class="mw-alert">{{scanError}}</p> <div class="mw-stats"><button v-for="card in cards" :key="card.id" :aria-pressed="filter===card.id" @click="filter=card.id"><strong>{{metrics[card.id]}}</strong><span>{{card.label}}</span></button></div>
 <div class="mw-queue-layout" :class="{'mw-inspecting':detail}"><section class="mw-surface mw-queue"><div class="mw-section-heading"><div><span class="mw-eyebrow">Your next move</span><h2>{{cards.find(card=>card.id===filter)?.label||'All issues'}}</h2></div><div class="mw-queue-tools"><select v-model="filter" aria-label="Filter issues"><option value="">All issues</option><option value="qaNone">QA not required</option><option v-for="card in cards" :key="card.id" :value="card.id">{{card.label}}</option></select><input v-model="query" aria-label="Search issues" placeholder="Search title or #issue"/></div></div><div v-if="!visible.length" class="mw-empty"><Icon name="check"/><h3>Nothing in this view.</h3><p>{{rows.length?'Choose another stage or clear your search.':'No issues match the saved scope. Try another label or clear it, then scan the release again.'}}</p></div><article v-for="row in visible" :key="row.issue.html_url" class="mw-issue"><div class="mw-issue-number">#{{row.issue.number}}</div><div class="mw-issue-copy"><button class="mw-issue-title" @click="inspected=row.issue.html_url">{{row.issue.title}}</button><div><span v-if="row.issue.milestoneTitle" class="mw-caption">{{row.issue.milestoneTitle}}</span><span v-if="row.issue.explicitlyTracked" class="mw-badge">Added individually</span><span class="mw-badge" :data-closed="row.closed">{{row.closed?'GitHub closed':'GitHub open'}}</span><span class="mw-badge">{{row.stage}}</span><span class="mw-caption">{{row.issue.assignees?.map(owner=>'@'+owner.login).join(', ')||'Unassigned'}}{{row.matches.length>1?` · ${row.matches.length} linked packages`:''}}</span></div></div><div class="mw-row-actions"><IssueReadiness :issue-url="row.issue.html_url" compact/><button class="mw-secondary" @click="open(row)">{{row.pkg?'Open package':'Create issue package'}}<Icon name="arrow"/></button></div></article></section><aside v-if="detail" class="mw-detail mw-surface" aria-label="Issue details"><div class="mw-section-heading"><span class="mw-eyebrow">#{{detail.issue.number}} · {{detail.issue.milestoneTitle||snapshot?.milestone.title}}</span><button class="mw-secondary" @click="inspected=''" aria-label="Close issue details">Close</button></div><h2>{{detail.issue.title}}</h2><p class="mw-detail-stage">{{detail.stage}}</p><p class="mw-caption">{{detail.issue.assignees?.map(owner=>'@'+owner.login).join(', ')||'Unassigned'}}</p><p class="mw-detail-body">{{detail.issue.body||'Open the GitHub issue for the full description.'}}</p><div class="mw-detail-actions"><button class="mw-primary" @click="open(detail)">{{detail.pkg?'Open issue package':'Create issue package'}}</button><IssueReadiness :issue-url="detail.issue.html_url" compact/><a :href="detail.issue.html_url" target="_blank" rel="noopener noreferrer">View on GitHub ↗</a></div><h3>Saved test cases · {{detail.pkg?.cases?.length||0}}</h3><ul><li v-for="c in detail.pkg?.cases||[]" :key="c.id">{{c.title}}</li></ul><p v-if="!detail.planned" class="mw-caption">Prepare test cases before starting validation.</p></aside></div>
<details v-if="reportMatches" class="mw-support"><summary>Readiness briefing · {{dailyReadiness.report.milestone}}</summary><DailyReadinessPanel :scope-config="dailyReadiness.report.config"/></details></div></template>
<style scoped>
.my-work{--mw-surface:var(--runway-card,#fff);--mw-text:var(--runway-ink,#203230);--mw-muted:var(--runway-muted,#657577);--mw-border:var(--runway-border,#dfe7e4);display:grid;gap:24px;color:var(--mw-text)}
:global(.dark) .my-work{--mw-surface:#1b2325;--mw-text:#e9f0ee;--mw-muted:#a0b3ae;--mw-border:#344541}
.mw-hero,.mw-section-heading,.mw-scope-heading,.mw-scope-bottom,.mw-snapshot{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.mw-hero h1{font-size:clamp(36px,5vw,64px);letter-spacing:-.05em;font-weight:700;line-height:1.2}.mw-dot{color:#319476}.mw-hero p{color:var(--mw-muted);margin-top:10px;max-width:620px}.mw-eyebrow{font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--mw-muted)}.mw-surface{background:var(--mw-surface);border:1px solid var(--mw-border);border-radius:20px;padding:24px}.mw-scope-heading span,.mw-snapshot span,.mw-caption,.mw-scope-bottom p{color:var(--mw-muted);font-size:12px}.mw-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:16px;margin:20px 0}.mw-milestone-field{display:grid;align-content:start;gap:8px;min-width:0}.mw-scope-shell>summary{cursor:pointer;font-weight:650;font-size:14px}.mw-scope-shell>summary span{font-size:12px;color:var(--mw-muted);font-weight:400;margin-left:15px}.mw-scope-shell[open]>summary{margin-bottom:24px}.mw-refresh-row{display:flex;gap:15px;justify-content:space-between;align-items:center;font-size:12px;color:var(--mw-muted)}.mw-fields label{display:flex;flex-direction:column;gap:8px;font-size:12px;font-weight:600}input,select{background:var(--mw-surface);color:var(--mw-text);border:1px solid var(--mw-border);padding:10px 12px;border-radius:9px;min-width:0}.mw-primary,.mw-secondary{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:11px 15px;border-radius:10px;font-size:13px;font-weight:600}.mw-primary{background:#16735e;color:white}.mw-secondary{border:1px solid var(--mw-border);background:var(--mw-surface)}button:disabled{opacity:.5;cursor:wait}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid #319476;outline-offset:3px}.mw-link{text-align:left;color:#319476;font-size:11px}.mw-scope-bottom p{max-width:630px}.mw-alert,.mw-notice{padding:14px 18px;border-radius:10px;background:#c08a2020;font-size:13px}.mw-notice{background:#31947618}.mw-stats{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}.mw-stats button{text-align:left;background:var(--mw-surface);border:1px solid var(--mw-border);border-radius:16px;padding:18px;display:flex;flex-direction:column;gap:12px}.mw-stats button[aria-pressed=true]{border-color:#319476;box-shadow:0 0 0 1px #319476}.mw-stats span{font-size:12px;color:var(--mw-muted);min-height:32px}.mw-stats strong{font-size:36px;line-height:1;font-weight:650;letter-spacing:-.04em}.mw-stats small{display:flex;align-items:center;gap:8px;font-size:10px;color:var(--mw-muted)}.mw-charts{display:grid;grid-template-columns:1fr 1fr;gap:20px}h2{font-size:21px;font-weight:650;letter-spacing:-.03em;margin-top:5px}.mw-coverage{height:20px;border-radius:20px;background:#c08a2030;overflow:hidden;margin:28px 0 15px}.mw-coverage i{display:block;background:#319476;height:100%}.mw-legend{display:flex;justify-content:space-between;gap:15px;font-size:12px;margin-bottom:16px}.mw-legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px}.mw-amber{background:#c08a20}.mw-green{background:#319476}.mw-charts svg{width:100%;height:95px;margin-top:12px}.mw-charts polyline{fill:none;stroke:#319476;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}.mw-axis{stroke:var(--mw-border);fill:none}.mw-trend-empty{padding:30px 0}.mw-history{font-size:11px;margin-bottom:12px;color:var(--mw-muted)}.mw-history ol{max-height:160px;overflow:auto}.mw-queue-tools{display:flex;gap:10px;flex-wrap:wrap}.mw-issue{display:flex;align-items:center;gap:18px;padding:20px 0;border-top:1px solid var(--mw-border)}.mw-queue>.mw-section-heading{margin-bottom:22px}.mw-row-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.mw-issue-number{color:var(--mw-muted);font-size:12px;min-width:55px}.mw-issue-copy{flex:1;min-width:0}.mw-issue-copy>a{font-size:15px;font-weight:600}.mw-issue-copy>div{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:9px}.mw-badge{font-size:10px;padding:4px 8px;border-radius:5px;background:#31947612}.mw-badge[data-closed=true]{background:#7760ba20}.mw-empty{text-align:center;padding:50px 20px;color:var(--mw-muted)}.mw-empty>svg{margin:0 auto 14px;width:32px;height:32px}.mw-empty h2,.mw-empty h3{color:var(--mw-text);margin-bottom:10px}.mw-journey{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;margin-top:28px;font-size:12px}.mw-departed summary{cursor:pointer;font-weight:600}.mw-departed p{margin:12px 0}.mw-departed a{font-size:13px}.mw-departed>div{margin-top:8px}@media(max-width:1100px){.mw-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.mw-charts{grid-template-columns:1fr}.mw-stats{grid-template-columns:repeat(2,1fr)}.mw-issue{flex-wrap:wrap}.mw-issue-copy{flex-basis:70%}.mw-surface{padding:18px}.mw-queue-tools{width:100%}.mw-queue-tools input{width:100%}}

.my-work{gap:16px}.mw-hero h1{font-size:32px}.mw-hero p{margin-top:4px;font-size:13px}.mw-surface{border-radius:10px;padding:16px}.mw-stats{display:flex;gap:6px;flex-wrap:wrap}.mw-stats button{display:flex;flex-direction:row;align-items:center;gap:8px;border-radius:6px;padding:8px 12px}.mw-stats strong{font-size:16px}.mw-stats span{font-size:11px;min-height:0}.mw-issue{padding:12px 0;gap:12px}.mw-issue-copy>a{font-size:13px}.mw-issue-copy>div{margin-top:5px}.mw-secondary{padding:7px 10px;font-size:11px}.mw-queue>.mw-section-heading{margin-bottom:12px}.mw-work-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.mw-support{border-top:1px solid var(--mw-border);padding-top:14px}.mw-support>summary{cursor:pointer;font-size:12px;color:var(--mw-muted);margin-bottom:12px}.mw-deadlines{display:flex;gap:16px;flex-wrap:wrap;font-size:11px;color:var(--mw-muted)}.mw-deadlines strong{color:var(--mw-text);margin-right:6px}

.mw-queue-layout{display:grid;gap:16px;align-items:start}.mw-inspecting{grid-template-columns:minmax(0,1fr) minmax(280px,360px)}.mw-issue-title{text-align:left;font-size:13px;font-weight:600;line-height:1.5}.mw-issue-title:hover{color:var(--runway-accent)}.mw-detail{position:sticky;top:100px}.mw-detail h2{font-size:19px;margin:16px 0 8px}.mw-detail-stage{color:var(--runway-accent);margin-bottom:6px;font-size:12px}.mw-detail-body{white-space:pre-wrap;font-size:12px;line-height:1.7;max-height:220px;overflow:auto;margin:16px 0}.mw-detail-actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-bottom:20px}.mw-detail-actions a{font-size:11px;color:var(--runway-accent)}.mw-detail h3{font-size:12px;margin:12px 0}.mw-detail li{font-size:12px;padding:6px 0;border-bottom:1px solid var(--mw-border)}@media(max-width:1000px){.mw-inspecting{grid-template-columns:1fr}.mw-detail{position:static;grid-row:1}}
</style>

<style scoped>.mw-empty{padding:22px}.mw-queue{border:0;padding:0;background:transparent}.mw-issue-title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;display:block}.mw-issue-copy>div{margin-top:2px}.mw-issue{padding:10px 0}.mw-queue h2{font-size:16px}</style>
<style scoped>.mw-release-radar{display:grid;gap:12px;padding:16px;background:color-mix(in srgb,var(--runway-accent) 5%,transparent);border:1px solid var(--mw-border);border-radius:10px}.mw-release-radar form{align-items:end}.mw-release-radar label{display:grid;gap:6px;font-size:12px;flex:1;max-width:480px}.mw-release-radar input{width:100%}.mw-release-lines{display:flex;flex-wrap:wrap;gap:8px}.mw-release-lines [aria-pressed=true]{border-color:var(--runway-accent);color:var(--runway-accent)}</style>

<style scoped>.mw-change{font-size:12px;padding:9px 0;border-bottom:1px solid var(--mw-border)}.mw-change a{font-weight:600}.mw-change p{color:var(--mw-muted);margin-top:4px}</style>
